package com.deepanshuraj.opspilot.rag;
import java.nio.charset.StandardCharsets; import java.security.*; import java.util.*; import org.springframework.stereotype.Service;
@Service public class IngestionService { public List<String> chunk(String text,int size,int overlap){text=text.replace("\r\n","\n").strip();if(text.isEmpty())return List.of();List<String> out=new ArrayList<>();for(int start=0;start<text.length();){int end=Math.min(text.length(),start+size);if(end<text.length()){int b=Math.max(text.lastIndexOf("\n\n",end),text.lastIndexOf(". ",end));if(b>start+size/2)end=b+1;}String piece=text.substring(start,end).strip();if(!piece.isEmpty())out.add(piece);if(end>=text.length())break;start=Math.max(end-overlap,start+1);}return out;} public String sha256(String text){try{return HexFormat.of().formatHex(MessageDigest.getInstance("SHA-256").digest(text.getBytes(StandardCharsets.UTF_8)));}catch(NoSuchAlgorithmException e){throw new IllegalStateException(e);}} }
